"""Images generated by a model are saved to the output folder of the conversation workspace."""

from __future__ import annotations

import base64
import hashlib

from services.agent_execution_service import AgentExecutionService

PNG = b"\x89PNG\r\n\x1a\nfake-image-bytes"
B64 = base64.b64encode(PNG).decode()
OPENAI_BLOCK = {"type": "image_generation_call", "id": "ig_abc123", "result": B64}
GEMINI_BLOCK = {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{B64}"}}
GEMINI_ID = hashlib.sha256(PNG).hexdigest()[:16]


def _saved(tmp_path):
    return {path.name: path.read_bytes() for path in tmp_path.rglob("generated_image_*.png")}


def test_save_generated_images_writes_openai_and_gemini_images_to_the_output_folder(tmp_path):
    AgentExecutionService().save_generated_images([OPENAI_BLOCK, GEMINI_BLOCK], str(tmp_path))

    saved = _saved(tmp_path)
    assert saved == {"generated_image_ig_abc123.png": PNG, f"generated_image_{GEMINI_ID}.png": PNG}
    assert all(path.parent.name == "output" for path in tmp_path.rglob("generated_image_*.png"))


def test_save_generated_images_ignores_everything_else(tmp_path):
    service = AgentExecutionService()

    service.save_generated_images([{"type": "text", "text": "hi"}, "stray", {"type": "image_generation_call", "id": "x"}], str(tmp_path))
    service.save_generated_images("plain text answer", str(tmp_path))
    service.save_generated_images([OPENAI_BLOCK], None)

    assert _saved(tmp_path) == {}


def test_extract_content_blocks_saves_images_and_keeps_the_placeholders(tmp_path):
    text = AgentExecutionService()._extract_content_blocks(
        [{"type": "text", "text": "Here it is"}, OPENAI_BLOCK], str(tmp_path)
    )

    assert text == "Here it is [Image saved: generated_image_ig_abc123.png]"
    assert list(_saved(tmp_path)) == ["generated_image_ig_abc123.png"]


def test_extract_content_blocks_without_working_dir_only_labels_the_image():
    assert AgentExecutionService()._extract_content_blocks([OPENAI_BLOCK, GEMINI_BLOCK]) == (
        "[Image generated] [Image generated]"
    )
